import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServerClient } from "@/lib/supabase";

export async function GET(request: NextRequest) {
  try {
    const supabase = getSupabaseServerClient();

    if (!supabase) {
      return NextResponse.json(
        { error: "Database connection failed" },
        { status: 500 }
      );
    }

    const { data, error } = await supabase
      .from("jobs")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Supabase error:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ jobs: data }, { status: 200 });
  } catch (error) {
    console.error("Error fetching jobs:", error);
    return NextResponse.json(
      { error: "Failed to fetch jobs" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const supabase = getSupabaseServerClient();

    if (!supabase) {
      return NextResponse.json(
        { error: "Database connection failed" },
        { status: 500 }
      );
    }

    // Validation
    const {
      title,
      description,
      required,
      minimum_salary,
      maximum_salary,
      country,
      city,
      location,
      remote_available,
      skills,
    } = body;

    const errors: Record<string, string> = {};

    if (!title?.trim()) errors.title = "Title is required";
    if (!description?.trim()) errors.description = "Description is required";
    if (!required || required < 1)
      errors.required = "Required positions must be at least 1";
    if (!minimum_salary || minimum_salary < 0)
      errors.minimum_salary = "Minimum salary must be a valid number";
    if (!maximum_salary || maximum_salary < minimum_salary)
      errors.maximum_salary = "Maximum salary must be greater than minimum";
    if (!country?.trim()) errors.country = "Country is required";
    if (!city?.trim()) errors.city = "City is required";
    if (!location?.trim()) errors.location = "Location is required";
    if (typeof remote_available !== "boolean")
      errors.remote_available = "Remote availability is required";
    if (!skills || !Array.isArray(skills) || skills.length === 0)
      errors.skills = "At least one skill is required";

    if (Object.keys(errors).length > 0) {
      return NextResponse.json({ errors }, { status: 400 });
    }

    const jobData = {
      title: title.trim(),
      description: description.trim(),
      required,
      minimum_salary,
      maximum_salary,
      country: country.trim(),
      city: city.trim(),
      location: location.trim(),
      remote_available,
      skills,
      created_at: new Date().toISOString(),
    };

    const { data, error } = await supabase
      .from("jobs")
      .insert([jobData])
      .select();

    if (error) {
      console.error("Supabase error:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json(
      { message: "Job created successfully", job: data?.[0] },
      { status: 201 }
    );
  } catch (error) {
    console.error("Error creating job:", error);
    return NextResponse.json(
      { error: "Failed to create job" },
      { status: 500 }
    );
  }
}
